Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

int gcd_of(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    double x, y, n;
    cin >> x >> y >> n;
    int num, den;
    double ratio = x / y;
    double min_diff = 1e9;

    if (y <= n) {
        num = static_cast<int>(x);
        den = static_cast<int>(y);
    } else {
        for (int i = n; i >= 1; --i) {
            int denom = i;
            double val = denom * ratio;
            int candidate;
            if (val - floor(val) <= 0.5)
                candidate = static_cast<int>(floor(val));
            else
                candidate = static_cast<int>(floor(val)) + 1;
            double current_ratio = static_cast<double>(candidate) / denom;
            double diff = fabs(current_ratio - ratio);
            if (diff <= min_diff) {
                min_diff = diff;
                num = candidate;
                den = denom;
            }
        }
    }
    int g = gcd_of(num, den);
    num /= g;
    den /= g;
    cout << num << "/" << den << "\n";
    return 0;
}
